macro_rules! deps {
    () => {
        Outcome!();
        Clone!();
        Default!();
        Options!();
    };
}

macro_rules! commit {
    () => {
        deps!();
        # [doc = ""] pub mod commit { # [doc = " The outcome produced by [`Repository::merge_commits()`](crate::Repository::merge_commits())."] # [derive (Clone)] pub struct Outcome < 'a > { # [doc = " The outcome of the actual tree-merge, with the tree editor to write to obtain the actual tree id."] pub tree_merge : crate :: merge :: tree :: Outcome < 'a > , # [doc = " The tree id of the base commit we used. This is either…"] # [doc = " * the single merge-base we found"] # [doc = " * the first of multiple merge-bases if [Options::with_use_first_merge_base()] was `true`."] # [doc = " * the merged tree of all merge-bases, which then isn't linked to an actual commit."] # [doc = " * an empty tree, if [Options::with_allow_missing_merge_base()] is enabled."] pub merge_base_tree_id : gix_hash :: ObjectId , # [doc = " The object ids of all the commits which were found to be merge-bases, or `None` if there was no merge-base."] pub merge_bases : Option < Vec < gix_hash :: ObjectId > > , # [doc = " A list of virtual commits that were created to merge multiple merge-bases into one, the last one being"] # [doc = " the one we used as merge-base for the merge."] # [doc = " As they are not reachable by anything they will be garbage collected, but knowing them provides options."] # [doc = " Would be empty if no virtual commit was needed at all as there was only a single merge-base."] # [doc = " Otherwise, the last commit id is the one with the `merge_base_tree_id`."] pub virtual_merge_bases : Vec < gix_hash :: ObjectId > , } # [doc = " A way to configure [`Repository::merge_commits()`](crate::Repository::merge_commits())."] # [derive (Default , Debug , Clone)] pub struct Options { allow_missing_merge_base : bool , tree_merge : crate :: merge :: tree :: Options , use_first_merge_base : bool , } impl From < gix_merge :: tree :: Options > for Options { fn from (value : gix_merge :: tree :: Options) -> Self { Options { tree_merge : value . into () , use_first_merge_base : false , allow_missing_merge_base : false , } } } impl From < crate :: merge :: tree :: Options > for Options { fn from (value : crate :: merge :: tree :: Options) -> Self { Options { tree_merge : value , use_first_merge_base : false , allow_missing_merge_base : false , } } } impl From < Options > for gix_merge :: commit :: Options { fn from (Options { allow_missing_merge_base , tree_merge , use_first_merge_base , } : Options ,) -> Self { gix_merge :: commit :: Options { allow_missing_merge_base , tree_merge : tree_merge . into () , use_first_merge_base , } } } # [doc = " Builder"] impl Options { # [doc = " If `true`, merging unrelated commits is allowed, with the merge-base being assumed as empty tree."] pub fn with_allow_missing_merge_base (mut self , allow_missing_merge_base : bool) -> Self { self . allow_missing_merge_base = allow_missing_merge_base ; self } # [doc = " If `true`, do not merge multiple merge-bases into one. Instead, just use the first one."] # [doc (alias = "no_recursive" , alias = "git2")] pub fn with_use_first_merge_base (mut self , use_first_merge_base : bool) -> Self { self . use_first_merge_base = use_first_merge_base ; self } } }
    };
}

commit!()